list_customers.code:
final response = await client.adminCustomers.getCustomers(
    queryParams: {'limit': 20, 'status': 'active'});
for (final customer in (response.map as Map)['customers'] as List) {
  print('${(customer as Map)['customer_id']} ${customer['email']}');
}

get_customer.code:
final response = await client.adminCustomers.getCustomer(123);
final customer = (response.map as Map)['customer'] as Map;
print(customer['email']);

count_customers.code:
final response = await client.adminCustomers
    .getCustomerCount(queryParams: {'status': 'active'});
print((response.map as Map)['total']);

check_email.code:
final response =
    await client.adminCustomers.getCustomerEmailExists('jane@example.com');
print((response.map as Map)['exists']);

export_customers.code:
import 'dart:io';

final response = await client.adminCustomers.getCustomerExport();
await File('customers.xlsx').writeAsBytes(response.map as List<int>);

create_customer.code:
final response = await client.adminCustomers.createCustomer({
  'customer': {
    'first_name': 'Jane',
    'last_name': 'Doe',
    'email': 'jane@example.com',
    'company': false,
  },
});
final customer = (response.map as Map)['customer'] as Map;
print(customer['customer_id']);

bulk_reset_passwords.code:
final response = await client.adminCustomers.bulkResetCustomerPasswords({
  'customer_ids': [123, 124],
});
print((response.map as Map)['total_queued']);

import_customers.code:
import 'dart:io';

final csv = await File('customers.csv').readAsBytes();
final response = await client.adminCustomers.importCustomers({
  'file': ['customers.csv', csv, 'text/csv'],
});
print((response.map as Map)['created']);

list_store_credit_adjustments.code:
final response = await client.adminCustomers
    .getCustomerStoreCreditAdjustments(123, queryParams: {'limit': 20});
final adjustments =
    (response.map as Map)['store_credit_adjustments'] as List;
for (final adjustment in adjustments) {
  print('${(adjustment as Map)['action']} ${adjustment['amount']}');
}

adjust_store_credit.code:
final response = await client.adminCustomers
    .createCustomerStoreCreditAdjustment(
        123, {'action': 'add', 'amount': 20, 'note': 'Refund'});
print((response.map as Map)['store_credit']);
